<script setup>import{useForm,usePage}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';defineProps({cart:Object});const page=usePage(),form=useForm({customer_name:page.props.auth.user?.name||'',email:page.props.auth.user?.email||'',phone:page.props.auth.user?.phone||'',address_line_1:'',address_line_2:'',city:'',region:'',notes:'',payment_method:'cash_on_delivery'}),money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:page.props.store.currency,maximumFractionDigits:0}).format(v||0);</script><template><AppLayout><div class="container-shell py-8"><h1 class="text-3xl font-black">Checkout</h1><form class="mt-6 grid gap-6 lg:grid-cols-[1fr_360px]" @submit.prevent="form.post('/checkout')"><div class="card p-5"><h2 class="font-black">Delivery details</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><label class="label">Full name</label><input v-model="form.customer_name" class="input"><p class="error">{{form.errors.customer_name}}</p></div><div><label class="label">Phone</label><input v-model="form.phone" class="input"></div><div><label class="label">Email</label><input v-model="form.email" type="email" class="input"></div><div><label class="label">City / district</label><input v-model="form.city" class="input"></div><div class="sm:col-span-2"><label class="label">Address</label><input v-model="form.address_line_1" class="input"></div><div><label class="label">Region</label><input v-model="form.region" class="input"></div><div><label class="label">Payment</label><select v-model="form.payment_method" class="input"><option value="cash_on_delivery">Cash on delivery</option><option value="mobile_money">Mobile money</option><option value="bank_transfer">Bank transfer</option></select></div><div class="sm:col-span-2"><label class="label">Notes</label><textarea v-model="form.notes" class="input" rows="4"></textarea></div></div></div><aside class="card h-fit p-5"><h2 class="font-black">Order summary</h2><div class="mt-4 space-y-2 text-sm"><div v-for="i in cart.items" :key="i.product.id" class="flex justify-between gap-3"><span>{{i.product.name}} × {{i.quantity}}</span><b>{{money(i.line_total)}}</b></div><div class="flex justify-between border-t pt-3 text-lg"><span>Total</span><b>{{money(cart.total)}}</b></div></div><button class="btn-primary mt-5 w-full" :disabled="form.processing">Place order</button></aside></form></div></AppLayout></template>
